  // Ref para rastrear se há mudanças não salvas nos horários
  const unsavedBusinessHoursRef = useRef<Record<string, BusinessHours> | null>(null);

  // Função para ajustar horário ao intervalo configurado
  const adjustTimeToInterval = (timeString: string): string => {
    if (!timeString || timeString === '00:00') return timeString;

    // Determinar o intervalo configurado
    let interval = 15; // Padrão: 15 em 15 min
    if (use60MinuteSchedule) {
      interval = 60;
    } else if (use20MinuteSchedule) {
      interval = 20;
    } else if (use15MinuteInterval) {
      interval = 30;
    }

    // Converter horário para minutos
    const [hours, minutes] = timeString.split(':').map(Number);
    const totalMinutes = hours * 60 + minutes;

    // Arredondar para o intervalo mais próximo
    const roundedMinutes = Math.round(totalMinutes / interval) * interval;

    // Converter de volta para string HH:mm
    const newHours = Math.floor(roundedMinutes / 60);
    const newMinutes = roundedMinutes % 60;

    return `${String(newHours).padStart(2, '0')}:${String(newMinutes).padStart(2, '0')}`;
  };

  // Valida se os horários de funcionamento são compatíveis com o intervalo (20, 30 ou 60 min).
  // Retorna lista de conflitos para exibir mensagem e bloquear a mudança.
  const getScheduleIntervalConflicts = (
    hours: Record<string, BusinessHours>,
    targetInterval: 20 | 30 | 60
  ): { day: string; dayLabel: string; field: string; fieldLabel: string; time: string }[] => {
    const dayLabels: Record<string, string> = {
      monday: 'Segunda-feira',
      tuesday: 'Terça-feira',
      wednesday: 'Quarta-feira',
      thursday: 'Quinta-feira',
      friday: 'Sexta-feira',
      saturday: 'Sábado',
      sunday: 'Domingo'
    };
    const fieldLabels: Record<string, string> = {
      open1: 'Abertura',
      close1: 'Fecha p/ intervalo',
      open2: 'Reabertura',
      close2: 'Fechamento'
    };
    const isTimeValid = (timeStr: string): boolean => {
      if (!timeStr || timeStr === '00:00') return true;
      const parts = timeStr.split(':');
      const minutes = (Number(parts[0]) || 0) * 60 + (Number(parts[1]) || 0);
      if (targetInterval === 20) return minutes % 20 === 0;
      if (targetInterval === 30) return minutes % 30 === 0;
      if (targetInterval === 60) return minutes % 60 === 0;
      return true;
    };
    const conflicts: { day: string; dayLabel: string; field: string; fieldLabel: string; time: string }[] = [];
    const days = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'] as const;
    const fields: ('open1' | 'close1' | 'open2' | 'close2')[] = ['open1', 'close1', 'open2', 'close2'];
    for (const day of days) {
      const h = (hours as any)?.[day];
      if (!h?.enabled) continue;
      for (const field of fields) {
        const time = String(h[field] || '');
        if (!time || time === '00:00') continue;
        if (!isTimeValid(time)) {
          conflicts.push({
            day,
            dayLabel: dayLabels[day] || day,
            field,
            fieldLabel: fieldLabels[field] || field,
            time
          });
        }
      }
    }
    return conflicts;
  };

  const handleBusinessHoursChange = (
    day: keyof typeof businessHours,
    field: 'enabled' | 'open1' | 'close1' | 'open2' | 'close2',
    value: string | boolean | null
  ) => {
    console.log('🕐 handleBusinessHoursChange chamado:', { day, field, value });

    // Se for um horário (não enabled), normalizar para nunca salvar null/vazio.
    // Isso evita estado quebrado tipo "08:00 -" e perda ao recarregar.
    let adjustedValue = value;
    if (field !== 'enabled') {
      const currentDay = businessHours[day];
      const raw = typeof value === 'string' ? value.trim() : '';
      if (!raw) {
        // open1/close1 são obrigatórios no funcionamento; mantém valor anterior.
        if (field === 'open1' || field === 'close1') {
          const currentFieldValue = String(currentDay?.[field] || '').trim();
          const fallback =
            currentFieldValue && currentFieldValue !== '00:00'
              ? currentFieldValue
              : (field === 'open1' ? '08:00' : '12:00');
          adjustedValue = adjustTimeToInterval(fallback);
          toast('Esse campo não pode ficar vazio. Mantivemos o último horário válido.', 'warning');
        } else {
          // open2/close2 vazios significam "sem segundo período" => salva como 00:00 para compatibilidade.
          adjustedValue = '00:00';
        }
      } else {
        adjustedValue = adjustTimeToInterval(raw);
        if (adjustedValue !== raw) {
          console.log(`⚡ Horário ajustado: ${raw} → ${adjustedValue}`);
        }
      }
    }

    const updatedHours = {
      ...businessHours,
      [day]: {
        ...businessHours[day],
        [field]: adjustedValue
      }
    };

    console.log('🕐 Horários atualizados:', updatedHours);

    setBusinessHours(updatedHours);

    // Salvar referência para salvar antes de sair da página
    unsavedBusinessHoursRef.current = updatedHours;

    // CANCELAR qualquer timeout anterior
    if (businessHoursAutoSaveTimeoutRef.current) {
      clearTimeout(businessHoursAutoSaveTimeoutRef.current);
      businessHoursAutoSaveTimeoutRef.current = null;
    }

    // SALVAR IMEDIATAMENTE - sem debounce!
    console.log('💾 SALVANDO IMEDIATAMENTE...');
    autoSaveBusinessHours(updatedHours).then(() => {
      console.log('✅ Salvo com sucesso!');
      unsavedBusinessHoursRef.current = null;
    }).catch((error) => {
      console.error('❌ Erro ao salvar:', error);
      // Manter a referência para tentar salvar novamente
    });
  };

  const isNoIntervalModeForDay = (dayHours?: BusinessHours | null): boolean => {
    const h = dayHours || ({} as BusinessHours);
    return String((h as any)?.open2 || '00:00') === '00:00' && String((h as any)?.close2 || '00:00') === '00:00';
  };

  // ✅ Modo "sem intervalo" (global): verdadeiro apenas quando TODOS os dias ativos estão sem intervalo.
  const isNoIntervalModeEnabled = (hours: Record<string, BusinessHours>): boolean => {
    const days = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
    return days.every((day) => {
      const h = (hours as any)?.[day];
      if (!h?.enabled) return true;
      return isNoIntervalModeForDay(h as BusinessHours);
    });
  };

  const toggleNoIntervalModeForDay = (day: keyof typeof businessHours, enable: boolean) => {
    const updatedHours = { ...businessHours } as Record<string, BusinessHours>;
    const current = updatedHours[day];
    if (!current) return;

    if (enable) {
      const currentClose1 = String(current.close1 || '').trim();
      const currentClose2 = String(current.close2 || '').trim();
      const finalClose =
        currentClose2 && currentClose2 !== '00:00'
          ? currentClose2
          : currentClose1 && currentClose1 !== '00:00'
            ? currentClose1
            : '12:00';

      updatedHours[day] = {
        ...current,
        close1: adjustTimeToInterval(String(finalClose)),
        open2: '00:00',
        close2: '00:00'
      };
    } else {
      const open2 = current.open2 && current.open2 !== '00:00' ? current.open2 : '14:00';
      const close2 = current.close2 && current.close2 !== '00:00' ? current.close2 : '20:00';

      let close1 = current.close1;
      if (!close1 || close1 === '00:00') close1 = '12:00';
      if (String(close1) === String(close2)) close1 = '12:00';

      updatedHours[day] = {
        ...current,
        close1: adjustTimeToInterval(String(close1 || '12:00')),
        open2: adjustTimeToInterval(String(open2)),
        close2: adjustTimeToInterval(String(close2))
      };
    }

    setBusinessHours(updatedHours);
    unsavedBusinessHoursRef.current = updatedHours;

    if (businessHoursAutoSaveTimeoutRef.current) {
      clearTimeout(businessHoursAutoSaveTimeoutRef.current);
      businessHoursAutoSaveTimeoutRef.current = null;
    }

    autoSaveBusinessHours(updatedHours).then(() => {
      unsavedBusinessHoursRef.current = null;
    }).catch((error) => {
      console.error('❌ Erro ao salvar:', error);
    });
  };

  // ✅ Padrão de horário do PROFISSIONAL baseado no que foi definido em Configurações (horários do estabelecimento)
  // Regra: o profissional herda por padrão o que foi configurado aqui, mas pode alterar no próprio profissional.
  const buildDefaultProfessionalWorkHoursFromEstablishment = () => {
    const WEEK_DAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'] as const;
    const getOr = (v: any, fallback: string) => (typeof v === 'string' && v.trim() ? v : fallback);

    const result: Record<string, any> = {};
    WEEK_DAYS.forEach((day) => {
      const h = (businessHours as any)?.[day] || {};
      const enabled = typeof h.enabled === 'boolean' ? h.enabled : true;

      const open1 = adjustTimeToInterval(getOr(h.open1, '08:00'));
      const close1 = adjustTimeToInterval(getOr(h.close1, '12:00'));
      const open2 = adjustTimeToInterval(getOr(h.open2, '14:00'));
      const close2 = adjustTimeToInterval(getOr(h.close2, '20:00'));

      if (isNoIntervalModeForDay(h as BusinessHours)) {
        // Sem intervalo: entrada = abertura, saída = fechamento (usa close1)
        result[day] = {
          enabled,
          entry_time: open1,
          break_start: '',
          break_end: '',
          exit_time: close1,
          no_break: true
        };
      } else {
        // Com intervalo: entrada/intervalo/saída seguindo os dois períodos
        const safeOpen2 = open2 && open2 !== '00:00' ? open2 : '14:00';
        const safeClose2 = close2 && close2 !== '00:00' ? close2 : '20:00';
        result[day] = {
          enabled,
          entry_time: open1,
          break_start: close1,
          break_end: safeOpen2,
          exit_time: safeClose2,
          no_break: false
        };
      }
    });

    return result;
  };

  const isNoIntervalModeEnabledForWorkHours = (data: Record<string, any>): boolean => {
    const WEEK_DAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'] as const;
    return WEEK_DAYS.every((day) => {
      const d = (data as any)?.[day];
      if (!d || d.enabled !== true) return true;
      const noBreakFlag = d.no_break === true;
      const bs = String(d.break_start || '');
      const be = String(d.break_end || '');
      return noBreakFlag || (bs.trim() === '' && be.trim() === '');
    });
  };

  const toggleNoIntervalModeForWorkHours = (enable: boolean) => {
    const WEEK_DAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'] as const;
    const est = businessHours as any;

    setWorkHoursData((prev: any) => {
      const next: any = { ...prev };
      WEEK_DAYS.forEach((day) => {
        const d = next[day] || {};
        // só ajustar dias "Aberto"; dias fechados mantém como está
        if (d.enabled !== true) {
          next[day] = { ...d, no_break: enable ? true : d.no_break };
          return;
        }

        if (enable) {
          // Sem intervalo: limpar intervalo e garantir saída
          const exit = typeof d.exit_time === 'string' && d.exit_time.trim()
            ? d.exit_time
            : adjustTimeToInterval(String(est?.[day]?.close1 || '20:00'));

          next[day] = {
            ...d,
            break_start: '',
            break_end: '',
            exit_time: exit,
            no_break: true
          };
        } else {
          // Com intervalo: preencher do padrão do estabelecimento (ou fallback)
          const close1 = adjustTimeToInterval(String(est?.[day]?.close1 || '12:00'));
          const open2 = adjustTimeToInterval(String(est?.[day]?.open2 || '14:00'));
          const close2Raw = String(est?.[day]?.close2 || '20:00');
          const close2 = adjustTimeToInterval(close2Raw === '00:00' ? '20:00' : close2Raw);

          const exit = typeof d.exit_time === 'string' && d.exit_time.trim() ? d.exit_time : close2;

          next[day] = {
            ...d,
            break_start: typeof d.break_start === 'string' && d.break_start.trim() ? d.break_start : close1,
            break_end: typeof d.break_end === 'string' && d.break_end.trim() ? d.break_end : open2,
            exit_time: exit,
            no_break: false
          };
        }
      });
      return next;
    });
  };

  const handleAddProfessional = async () => {
    if (!establishment) return;
    // ✅ Plano PRATA: limite de 1 profissional
    if (Boolean((establishment as any)?.plan_prata_active) && professionals.length >= 1) {
      openPlanUpgradeModal();
      return;
    }

    // ⚠️ IMPORTANTE: padrão automático de horários do profissional
    // Só aplicar em contas NOVAS / que ainda NÃO terminaram o quiz/onboarding.
    const shouldApplyDefaultsForProfessionals = onboardingStep < 4;

    const newProfessional = {
      id: uuidv4(),
      name: '',
      specialties: [],
      percentage: 100, // Percentual padrão de 100%
      whatsapp: '', // ✅ Campo WhatsApp
      specific_services: [], // ✅ Campo serviços específicos
      ...(shouldApplyDefaultsForProfessionals ? { work_hours: buildDefaultProfessionalWorkHoursFromEstablishment() } : {})
    };

    // Adiciona a senha padrão '0000' para o novo profissional
    const newPin = {
      professional_id: newProfessional.id,
      pin: '0000'
    };

    await enqueueEstablishmentProfessionalsWrite(async () => {
      try {
        // Proteção anti-perda: usar base do banco + estado local para não sobrescrever lista em cenários de estado transitório.
        const { data: establishmentDataSafe, error: fetchSafeError } = await supabase
          .from('establishments')
          .select('professionals, professionals_pins')
          .eq('id', establishment.id)
          .single();

        if (fetchSafeError) {
          throw fetchSafeError;
        }

        const dbProfessionalsSafe = Array.isArray((establishmentDataSafe as any)?.professionals)
          ? ((establishmentDataSafe as any).professionals as any[])
          : [];
        const dbPinsSafe = Array.isArray((establishmentDataSafe as any)?.professionals_pins)
          ? ((establishmentDataSafe as any).professionals_pins as any[])
          : [];

        const baseProfessionalsById = new Map<string, any>();
        dbProfessionalsSafe.forEach((p: any) => {
          const id = String(p?.id || '').trim();
          if (id) baseProfessionalsById.set(id, p);
        });
        professionals.forEach((p: any) => {
          const id = String(p?.id || '').trim();
          if (id) baseProfessionalsById.set(id, p);
        });

        const updatedProfessionals = [...Array.from(baseProfessionalsById.values()), newProfessional];

        const pinsByProfessionalId = new Map<string, any>();
        dbPinsSafe.forEach((pin: any) => {
          const professionalId = String(pin?.professional_id || '').trim();
          if (professionalId) pinsByProfessionalId.set(professionalId, pin);
        });
        (establishment.professionals_pins || []).forEach((pin: any) => {
          const professionalId = String(pin?.professional_id || '').trim();
          if (professionalId) pinsByProfessionalId.set(professionalId, pin);
        });
        pinsByProfessionalId.set(newPin.professional_id, newPin);
        const updatedPins = Array.from(pinsByProfessionalId.values());

        const { error } = await supabase
          .from('establishments')
          .update({
            professionals: updatedProfessionals,
            professionals_pins: updatedPins
          })
          .eq('id', establishment.id);

        if (error) throw error;

        setProfessionals(updatedProfessionals);
        setEstablishment({
          ...establishment,
          professionals: updatedProfessionals,
          professionals_pins: updatedPins
        });

        toast.success('Profissional adicionado à lista! Agora preencha o nome e clique em "Salvar Profissionais".');

        // Scroll até o novo profissional após o DOM ser atualizado
        setTimeout(() => {
          const newProfessionalElement = document.getElementById(`professional-${newProfessional.id}`);
          if (newProfessionalElement) {
            // Scroll com offset para ficar um pouco mais acima
            const elementPosition = newProfessionalElement.getBoundingClientRect().top;
            const offsetPosition = elementPosition + window.pageYOffset - 100; // 100px acima
            window.scrollTo({ top: offsetPosition, behavior: 'smooth' });

            // Destacar o novo profissional temporariamente
            newProfessionalElement.style.transition = 'box-shadow 0.3s';
            newProfessionalElement.style.boxShadow = '0 0 20px rgba(59, 130, 246, 0.5)';

            // Destacar o campo de nome do profissional
            const nameInput = newProfessionalElement.querySelector('input[type="text"]') as HTMLInputElement;
            if (nameInput) {
              nameInput.style.transition = 'all 0.3s';
              nameInput.style.borderColor = '#3b82f6';
              nameInput.style.borderWidth = '2px';
              nameInput.style.backgroundColor = '#1e3a8a';
              nameInput.style.boxShadow = '0 0 15px rgba(59, 130, 246, 0.6)';
              nameInput.focus();

              // Adicionar placeholder destacado
              const originalPlaceholder = nameInput.placeholder;
              nameInput.placeholder = '⚠️ DIGITE O NOME DO PROFISSIONAL AQUI ⚠️';

              setTimeout(() => {
                newProfessionalElement.style.boxShadow = '';
                nameInput.style.borderColor = '';
                nameInput.style.borderWidth = '';
                nameInput.style.backgroundColor = '';
                nameInput.style.boxShadow = '';
                nameInput.placeholder = originalPlaceholder;
              }, 4000);
            }

            setTimeout(() => {
              newProfessionalElement.style.boxShadow = '';
            }, 2000);
          }
        }, 100);
      } catch (error) {
        console.error('Erro ao adicionar profissional:', error);
        toast.error('Erro ao adicionar profissional');
      }
    });
  };

  const handleRemoveProfessional = async (id: string) => {
    console.log('Removendo profissional:', id);
    if (!establishment?.id) {
      setProfessionals(prev => prev.filter(p => p.id !== id));
      return;
    }

    const professionalToRemove = professionals.find((p) => String(p.id) === String(id));
    if (!professionalToRemove) return;

    await enqueueEstablishmentProfessionalsWrite(async () => {
      try {
        const { data: establishmentData, error: fetchError } = await supabase
          .from('establishments')
          .select('professionals, professionals_pins, deleted_professionals')
          .eq('id', establishment.id)
          .single();
        if (fetchError) throw fetchError;

        const dbProfessionals = Array.isArray(establishmentData?.professionals)
          ? (establishmentData.professionals as any[])
          : [];
        const dbPins = Array.isArray(establishmentData?.professionals_pins)
          ? (establishmentData.professionals_pins as any[])
          : [];
        const dbDeleted = Array.isArray(establishmentData?.deleted_professionals)
          ? (establishmentData.deleted_professionals as any[])
          : [];

        const nextProfessionals = dbProfessionals.filter((p: any) => String(p?.id || '') !== String(id));
        const alreadyDeleted = dbDeleted.some((p: any) => String(p?.id || '') === String(id));
        const now = new Date().toISOString();
        const removedPayload = {
          ...(dbProfessionals.find((p: any) => String(p?.id || '') === String(id)) || professionalToRemove),
          deleted_at: now,
        };
        const nextDeleted = alreadyDeleted ? dbDeleted : [...dbDeleted, removedPayload];

        const { error: updateError } = await supabase
          .from('establishments')
          .update({
            professionals: nextProfessionals,
            professionals_pins: dbPins,
            deleted_professionals: nextDeleted,
          })
          .eq('id', establishment.id);
        if (updateError) throw updateError;

        setProfessionals(nextProfessionals as any);
        setEstablishment({
          ...establishment,
          professionals: nextProfessionals as any,
          professionals_pins: dbPins as any,
          deleted_professionals: nextDeleted as any,
        });
        toast.success(`${professionalToRemove.name || 'Profissional'} removido e enviado para o histórico.`);
      } catch (error: any) {
        console.error('Erro ao remover profissional:', error);
        toast(
          [error?.message, error?.code, error?.details, error?.hint].filter(Boolean).join(' | ') || 'Erro ao remover profissional',
          'error'
        );
      }
    });
  };

  const handleProfessionalChange = (id: string, field: keyof Professional, value: string | string[] | number) => {
    console.log('Atualizando profissional:', { id, field, value });
    const normalizedValue =
      field === 'percentage'
        ? normalizeProfessionalPercentage(value)
        : value;
    setProfessionals(prev => {
      const updated = prev.map(p =>
        p.id === id ? { ...p, [field]: normalizedValue } : p
      );
      console.log('🔄 Profissionais após atualização:', updated);
      return updated;
    });

    // Removido salvamento automático para evitar loops
  };

  const mergeProfessionalsPreservingCriticalFields = (nextProfessionals: any[], dbProfessionals: any[]) => {
    return nextProfessionals.map((localProfessional: any) => {
      const dbProfessional = dbProfessionals.find((p: any) => String(p?.id) === String(localProfessional?.id)) || {};
      const mergedProfessional = { ...dbProfessional, ...localProfessional };

      const mergedBlockedHours = mergeBlockedHoursMapsUnion(
        (dbProfessional as any)?.blocked_hours,
        (localProfessional as any)?.blocked_hours
      );
      (mergedProfessional as any).blocked_hours =
        Object.keys(mergedBlockedHours).length > 0 ? mergedBlockedHours : {};

      const localAbsences = (localProfessional as any)?.absences;
      const dbAbsences = (dbProfessional as any)?.absences;
      (mergedProfessional as any).absences = Array.isArray(localAbsences)
        ? localAbsences
        : Array.isArray(dbAbsences)
          ? dbAbsences
          : [];

      const localWorkHours = (localProfessional as any)?.work_hours;
      const dbWorkHours = (dbProfessional as any)?.work_hours;
      (mergedProfessional as any).work_hours = localWorkHours ?? dbWorkHours ?? null;

      return mergedProfessional;
    });
  };

  const persistProfessionalSnapshot = async (
    reason: string,
    payload?: {
      professionals?: any[];
      professionals_pins?: any[];
      services_with_prices?: any[];
    }
  ) => {
    if (!establishment?.id) return;
    try {
      let professionalsForSnapshot = payload?.professionals;
      let pinsForSnapshot = payload?.professionals_pins;
      let servicesForSnapshot = payload?.services_with_prices;

      if (!Array.isArray(professionalsForSnapshot) || !Array.isArray(pinsForSnapshot) || !Array.isArray(servicesForSnapshot)) {
        const { data, error } = await supabase
          .from('establishments')
          .select('professionals, professionals_pins, services_with_prices')
          .eq('id', establishment.id)
          .single();
        if (error) throw error;
        professionalsForSnapshot = Array.isArray(data?.professionals) ? (data.professionals as any[]) : [];
        pinsForSnapshot = Array.isArray((data as any)?.professionals_pins) ? ((data as any).professionals_pins as any[]) : [];
        servicesForSnapshot = Array.isArray((data as any)?.services_with_prices) ? ((data as any).services_with_prices as any[]) : [];
      }

      const snapshotPayload = {
        version: 1,
        professionals: professionalsForSnapshot || [],
        professionals_pins: pinsForSnapshot || [],
        services_with_prices: servicesForSnapshot || [],
      };

      const { error: snapshotError } = await (supabase as any)
        .from('establishment_professional_snapshots')
        .insert({
          establishment_id: establishment.id,
          reason,
          snapshot: snapshotPayload,
          created_by_user_id: String(user?.id || '').trim() || null,
        });

      if (snapshotError) {
        const code = String((snapshotError as any)?.code || '');
        const message = String((snapshotError as any)?.message || '').toLowerCase();
        const isMissingTable = code === '42P01' || message.includes('does not exist');
        if (!isMissingTable) {
          console.warn('Falha ao salvar snapshot de profissionais:', snapshotError);
        }
      }
    } catch (error) {
      console.warn('Falha ao criar snapshot de profissionais:', error);
    }
  };

  const getLatestSnapshotProfessionalById = async (professionalId: string): Promise<any | null> => {
    if (!establishment?.id || !professionalId) return null;
    try {
      const { data, error } = await (supabase as any)
        .from('establishment_professional_snapshots')
        .select('snapshot, created_at')
        .eq('establishment_id', establishment.id)
        .order('created_at', { ascending: false })
        .limit(30);
      if (error) {
        const code = String((error as any)?.code || '');
        const message = String((error as any)?.message || '').toLowerCase();
        if (code === '42P01' || message.includes('does not exist')) return null;
        throw error;
      }

      for (const row of data || []) {
        const snapshot = (row as any)?.snapshot || {};
        const snapshotProfessionals = Array.isArray(snapshot?.professionals) ? snapshot.professionals : [];
        const match = snapshotProfessionals.find((p: any) => String(p?.id || '').trim() === professionalId);
        if (match) return match;
      }
      return null;
    } catch (error) {
      console.warn('Falha ao buscar profissional em snapshot:', error);
      return null;
    }
  };

  const saveProfessionalsSafely = async (nextProfessionals: any[]) => {
    if (!establishment?.id) {
      return {
        error: new Error('Estabelecimento não encontrado'),
        professionals: nextProfessionals
      };
    }

    return enqueueEstablishmentProfessionalsWrite(async () => {
      const { data: establishmentData, error: fetchError } = await supabase
        .from('establishments')
        .select('professionals')
        .eq('id', establishment.id)
        .single();

      if (fetchError) {
        return { error: fetchError, professionals: nextProfessionals };
      }

      const dbProfessionals = (establishmentData?.professionals || []) as any[];
      const safeProfessionals = mergeProfessionalsPreservingCriticalFields(nextProfessionals, dbProfessionals);

      // Proteção anti-perda: evita sobrescrever com lista vazia por retorno inconsistente.
      if (dbProfessionals.length === 0 && Array.isArray(nextProfessionals) && nextProfessionals.length > 0) {
        return {
          error: new Error('Proteção ativada: banco retornou profissionais vazios. Operação bloqueada para evitar perda de dados.'),
          professionals: nextProfessionals
        };
      }
      if (Array.isArray(nextProfessionals) && nextProfessionals.length > 0 && safeProfessionals.length === 0) {
        return {
          error: new Error('Proteção ativada: atualização bloqueada para evitar gravar profissionais vazios.'),
          professionals: nextProfessionals
        };
      }

      await persistProfessionalSnapshot('before_save_professionals', {
        professionals: dbProfessionals,
        professionals_pins: establishment.professionals_pins || [],
        services_with_prices: servicesWithPrices || [],
      });

      const reconciledProfessionals = await reconcileProfessionalsBlockedHoursWithHistory(
        establishment.id,
        safeProfessionals
      );

      const { error: updateError } = await supabase
        .from('establishments')
        .update({ professionals: reconciledProfessionals })
        .eq('id', establishment.id);

      return { error: updateError, professionals: reconciledProfessionals };
    });
  };

