  // Função para transferir agendamento entre profissionais
  const transferAppointment = async (appointmentId: string, fromProfessionalId: string, toProfessionalId: string) => {
    if (!establishment) return;

    console.log('🔄 TRANSFERINDO AGENDAMENTO...');
    console.log(`De: ${fromProfessionalId} → Para: ${toProfessionalId}`);

    try {
      // Verificar se o profissional de destino está disponível no horário
      const appointment = appointments.find(apt => apt.id === appointmentId);
      if (!appointment) {
        toast.error('Agendamento não encontrado!');
        return;
      }

      // Verificar conflito de horário
      const hasConflict = appointments.some(apt =>
        apt.professional === toProfessionalId &&
        apt.appointment_date === appointment.appointment_date &&
        apt.appointment_time === appointment.appointment_time &&
        apt.id !== appointmentId
      );

      if (hasConflict) {
        toast.error('Profissional de destino já tem agendamento neste horário!');
        return;
      }

      // Encontrar nomes dos profissionais
      const fromProfessional = professionals.find(p => p.id === fromProfessionalId);
      const toProfessional = professionals.find(p => p.id === toProfessionalId);

      if (!fromProfessional || !toProfessional) {
        toast.error('Profissional não encontrado!');
        return;
      }

      // Atualizar agendamento
      const { error } = await supabase
        .from('appointments')
        .update({
          professional: toProfessionalId,
          observation: (appointment.observation || '') + ` [Transferido de ${fromProfessional.name} para ${toProfessional.name}]`
        })
        .eq('id', appointmentId);

      if (error) {
        console.error('❌ Erro ao transferir agendamento:', error);
        toast.error('Erro ao transferir agendamento');
        return;
      }

      // Recarregar dados
      await fetchAppointments();

      toast.success(`Agendamento transferido de ${fromProfessional.name} para ${toProfessional.name}!`);

    } catch (error) {
      console.error('❌ Erro ao transferir agendamento:', error);
      toast.error('Erro ao transferir agendamento');
    }
  };


  // Função para obter o nome do profissional pelo ID
  const getProfessionalName = (professionalId: string): string => {
    if (professionalId === 'all') return 'Todos os profissionais';
    if (professionalId === '') return 'Nenhum profissional selecionado';

    // Primeiro tenta encontrar por ID
    const professionalById: Professional | undefined = professionals.find(p => p.id === professionalId);
    if (professionalById) return professionalById.name;

    // Se não encontrar por ID, pode ser que seja o nome diretamente
    const professionalByName: Professional | undefined = professionals.find(p => p.name === professionalId);
    if (professionalByName) return professionalByName.name;

    return 'Profissional não encontrado';
  };

  // Função para buscar e agrupar clientes
  const fetchClients = async () => {
    if (!establishment) return;

    try {
      // Busca todos os agendamentos do estabelecimento para obter os clientes + estatísticas.
      const baseAppointmentsSelect =
        'client_id, client_name, client_whatsapp, status, price, total_price, appointment_date, appointment_time';
      const { data: appointmentsData, error: appointmentsError } = await supabase
        .from('appointments')
        .select(baseAppointmentsSelect)
        .eq('establishment_id', establishment.id)
        .not('client_whatsapp', 'is', null) // Apenas agendamentos com WhatsApp
        .order('created_at', { ascending: false });
      if (appointmentsError) throw appointmentsError;

      const appointmentDateTimeToTs = (dateStr: string, timeRaw: unknown): number | null => {
        const [y, m, d] = String(dateStr || '').split('-').map((x) => parseInt(x, 10));
        if (!y || !m || !d) return null;
        const t = String(timeRaw ?? '12:00').trim();
        const [hh, mm] = t.split(':').map((x) => parseInt(x, 10));
        const h = Number.isFinite(hh) ? hh : 12;
        const min = Number.isFinite(mm) ? mm : 0;
        return new Date(y, m - 1, d, h, min, 0, 0).getTime();
      };

      const normalizeWhatsappKey = (raw: any) => {
        const onlyDigits = String(raw || '').replace(/\D/g, '');
        let digits = onlyDigits;
        if (!digits) return '';

        while (digits.startsWith('55') && digits.length > 11) {
          digits = digits.slice(2);
        }

        if (digits.startsWith('55')) {
          const after = digits.slice(2);
          const otherDDI = [
            { code: '351', minLength: 11 },
            { code: '244', minLength: 11 },
            { code: '54', minLength: 11 },
            { code: '56', minLength: 10 },
            { code: '34', minLength: 10 },
            { code: '1', minLength: 10 },
          ];
          const hasOther = otherDDI.some(({ code, minLength }) => after.startsWith(code) && after.length >= minLength);
          if (hasOther) return after;

          if (after.length === 10 || after.length === 11) return after;
        }

        if (digits.length > 11) return digits.slice(-11);
        return digits;
      };

      const possibleWhatsappLookupKeys = (raw: any): string[] => {
        const digits = String(raw || '').replace(/\D/g, '');
        const normalized = normalizeWhatsappKey(raw);
        if (!digits && !normalized) return [];
        const keys = new Set<string>();
        if (digits) keys.add(digits);
        if (normalized) keys.add(normalized);
        if (digits.startsWith('55') && digits.length > 2) keys.add(digits.slice(2));
        if (normalized && (normalized.length === 10 || normalized.length === 11)) {
          keys.add(`55${normalized}`);
        }
        return Array.from(keys).filter(Boolean);
      };

      const lastVisitByWhatsapp = new Map<string, number>();
      const completedVisitsInWindowByWhatsapp = new Map<string, number>();
      const completedClientInfoByWhatsapp = new Map<
        string,
        { name: string; whatsapp: string; latestCompletedTs: number }
      >();
      const nowTs = Date.now();
      const sixtyDaysAgoTs = nowTs - (60 * 24 * 60 * 60 * 1000);
      (appointmentsData || []).forEach((raw: any) => {
        const key = normalizeWhatsappKey(raw?.client_whatsapp);
        if (!key) return;
        const st = String(raw?.status || '').toLowerCase();
        const ds = String(raw?.appointment_date || '').trim();
        if (st === 'cancelled' || !ds) return;
        const ts = appointmentDateTimeToTs(ds, raw?.appointment_time);
        if (ts == null || !Number.isFinite(ts)) return;
        if (st === 'completed' && ts >= sixtyDaysAgoTs && ts <= nowTs) {
          completedVisitsInWindowByWhatsapp.set(
            key,
            Number(completedVisitsInWindowByWhatsapp.get(key) || 0) + 1
          );

          const rawClientName = String(raw?.client_name || '').trim();
          const displayName = rawClientName || 'Cliente sem nome';
          const displayWhatsapp = String(raw?.client_whatsapp || '').replace(/\D/g, '') || key;
          const prevInfo = completedClientInfoByWhatsapp.get(key);
          if (!prevInfo || ts > prevInfo.latestCompletedTs) {
            completedClientInfoByWhatsapp.set(key, {
              name: displayName,
              whatsapp: displayWhatsapp,
              latestCompletedTs: ts,
            });
          }
        }
        const prev = lastVisitByWhatsapp.get(key);
        if (prev == null || ts > prev) lastVisitByWhatsapp.set(key, ts);
      });

      const singleVisitClientList: ClientInsightListItem[] = Array.from(completedVisitsInWindowByWhatsapp.entries())
        .filter(([, completedVisits]) => completedVisits === 1)
        .map(([whatsappKey, completedVisits]) => {
          const info = completedClientInfoByWhatsapp.get(whatsappKey);
          return {
            whatsapp: info?.whatsapp || whatsappKey,
            name: info?.name || 'Cliente sem nome',
            completedVisits,
            lastCompletedAt: Number(info?.latestCompletedTs || 0),
          };
        })
        .sort((a, b) => b.lastCompletedAt - a.lastCompletedAt);

      setClientInsightsLast60d({
        singleVisitClients: singleVisitClientList.length,
      });
      setSingleVisitClientListLast60d(singleVisitClientList);

      if (!appointmentsData || appointmentsData.length === 0) {
        setClientInsightsLast60d({
          singleVisitClients: 0,
        });
        setSingleVisitClientListLast60d([]);
        // Mesmo sem agendamentos, carregar clientes manuais
        const manualClients = await loadManualClientsFromStorage();

        const uniqueClients: Client[] = Object.values(manualClients).map((manualClient: any) => ({
          id: `manual_${manualClient.whatsapp}`,
          whatsapp: manualClient.whatsapp,
          name: manualClient.name,
          appointmentCount: 0,
          isSubscriber: false,
          birthday: manualClient.birthday,
          forceAdvancePayment: manualClient.forceAdvancePayment === true
        }));

        setClients(uniqueClients);
        return;
      }

      // Coleta IDs únicos dos agendamentos:
      // - allClientIds: para mapear assinatura (inclui IDs manuais quando existirem)
      // - uniqueClientIds: apenas IDs não manuais para lookup de profile
      const allClientIds = [
        ...new Set(
          (appointmentsData || [])
            .map((apt: any) => String(apt?.client_id || '').trim())
            .filter(Boolean)
        ),
      ];
      const uniqueClientIds = allClientIds.filter((id) => !id.startsWith('manual_'));
      const todayDateKey = format(new Date(), 'yyyy-MM-dd');


      // Buscar todos os perfis disponíveis para encontrar correspondências
      const { data: allProfilesData, error: allProfilesError } = await supabase
        .from('profiles')
        .select('id, user_id, name, is_subscriber, birthday');

      if (allProfilesError) throw allProfilesError;


      // Criar um mapa de perfis por user_id e por id
      const profilesMap = new Map();
      allProfilesData?.forEach(profile => {
        profilesMap.set(profile.user_id, profile);
        profilesMap.set(profile.id, profile);
      });

      // Encontrar perfis correspondentes aos client_ids
      const profilesData = uniqueClientIds
        .map(clientId => profilesMap.get(clientId))
        .filter(Boolean);


      const subscriptionStatusByClientId = new Map<string, 'paid' | 'expired'>();
      const subscriptionStatusByWhatsapp = new Map<string, 'paid' | 'expired'>();
      {
        let { data: subscriptionsData, error: subscriptionsError } = await supabase
          .from('client_subscriptions')
          .select('client_id, payment_status, end_date, client_whatsapp, subscriber_whatsapp')
          .eq('establishment_id', establishment.id);

        if (subscriptionsError) {
          const msg = String((subscriptionsError as any)?.message || '').toLowerCase();
          const missingPhoneCols =
            msg.includes('client_whatsapp') || msg.includes('subscriber_whatsapp');
          if (missingPhoneCols) {
            const fallback = await supabase
              .from('client_subscriptions')
              .select('client_id, payment_status, end_date')
              .eq('establishment_id', establishment.id)
              .in('client_id', allClientIds);
            subscriptionsData = fallback.data as any;
            subscriptionsError = fallback.error as any;
          }
        }

        if (subscriptionsError) {
          console.warn('⚠️ Não foi possível carregar status de assinatura em Meus Clientes:', subscriptionsError);
        } else {
          (subscriptionsData || []).forEach((row: any) => {
            const clientId = String(row?.client_id || '').trim();
            if (!clientId) return;
            const paymentStatus = String(row?.payment_status || '').toLowerCase().trim();
            const endDate = String(row?.end_date || '').slice(0, 10);
            const isActiveByEndDate = Boolean(endDate) && endDate >= todayDateKey;
            const isPaidAndActive = paymentStatus === 'paid' && isActiveByEndDate;
            const previous = subscriptionStatusByClientId.get(clientId);
            if (isPaidAndActive) {
              subscriptionStatusByClientId.set(clientId, 'paid');
            } else if (!previous) {
              subscriptionStatusByClientId.set(clientId, 'expired');
            }

            const phoneCandidates = Array.from(
              new Set([
                ...possibleWhatsappLookupKeys(row?.client_whatsapp),
                ...possibleWhatsappLookupKeys(row?.subscriber_whatsapp),
              ])
            )
              .map((phone) => normalizeWhatsappKey(phone))
              .filter(Boolean);
            phoneCandidates.forEach((phoneKey) => {
              const previousPhone = subscriptionStatusByWhatsapp.get(phoneKey);
              if (isPaidAndActive) {
                subscriptionStatusByWhatsapp.set(phoneKey, 'paid');
              } else if (!previousPhone) {
                subscriptionStatusByWhatsapp.set(phoneKey, 'expired');
              }
            });
          });
        }
      }

      // Cria um mapa de perfis para acesso rápido (user_id -> profile e id -> profile)
      const profilesMapForClients = new Map<
        string,
        { id: string; user_id?: string | null; name: string; is_subscriber: boolean; birthday: string | null }
      >();
      profilesData?.forEach(profile => {
        const profileData = {
          id: profile.id, // ID real do perfil para usar no update
          user_id: profile.user_id,
          name: profile.name,
          is_subscriber: profile.is_subscriber,
          birthday: profile.birthday
        };

        // Mapear tanto por user_id quanto por id para cobrir ambos os casos
        if (profile.user_id) {
          profilesMapForClients.set(profile.user_id, profileData);
        }
        profilesMapForClients.set(profile.id, profileData);

      });

      // Mapeia e agrupa os clientes a partir dos dados de agendamento e perfis
      const clientsMap = new Map<
        string,
        {
          id: string;
          name: string;
          count: number;
          completed: number;
          spent: number;
          isSubscriber: boolean;
          birthday: string | null;
          whatsapp: string;
          subscriberPaymentStatus: 'paid' | 'expired' | null;
        }
      >();

      appointmentsData.forEach(appointment => {
        const rawWhatsapp = (appointment as any).client_whatsapp;
        const key = normalizeWhatsappKey(rawWhatsapp);
        if (key) {
          const currentClient = clientsMap.get(key);
          const profileInfo = profilesMapForClients.get(appointment.client_id); // Buscar pelo client_id (que corresponde ao user_id)
          const whatsappLookupKeys = Array.from(
            new Set(possibleWhatsappLookupKeys(rawWhatsapp).map((phone) => normalizeWhatsappKey(phone)).filter(Boolean))
          );
          const subscriptionLookupIds = [
            String(appointment.client_id || '').trim(),
            String(profileInfo?.id || '').trim(),
            String(profileInfo?.user_id || '').trim(),
          ].filter(Boolean);
          const subscriberPaymentStatus =
            (subscriptionLookupIds
              .map((lookupId) => subscriptionStatusByClientId.get(lookupId))
              .find(Boolean) as 'paid' | 'expired' | undefined) ||
            (whatsappLookupKeys
              .map((phoneKey) => subscriptionStatusByWhatsapp.get(phoneKey))
              .find(Boolean) as 'paid' | 'expired' | undefined) ||
            null;
          const hasSubscriptionRecord = subscriberPaymentStatus !== null;
          const isSubscriber =
            profileInfo?.is_subscriber === true ||
            Boolean((appointment as any)?.is_subscriber) ||
            hasSubscriptionRecord;
          const birthday = profileInfo?.birthday || null;
          const profileId = profileInfo?.id || appointment.client_id; // Usar o ID real do perfil para updates

          // Usa o nome do perfil se disponível e mais recente, ou o nome do agendamento
          const clientName = profileInfo?.name || appointment.client_name || 'Cliente Desconhecido';

          const st = String((appointment as any).status || '');
          const isDone = st === 'completed';
          const baseValue = Number((appointment as any).total_price ?? (appointment as any).price ?? 0);
          const safeValue = Number.isFinite(baseValue) ? baseValue : 0;

          if (currentClient) {
            // manter whatsapp "bonito" (preferir o que já está salvo, senão o que veio agora)
            const nextWhatsapp = currentClient.whatsapp || String(rawWhatsapp || '').replace(/\D/g, '') || key;
            clientsMap.set(key, {
              id: profileId, // Usar o ID real do perfil
              name: clientName,
              count: currentClient.count + 1,
              completed: currentClient.completed + (isDone ? 1 : 0),
              spent: currentClient.spent + (isDone ? safeValue : 0),
              isSubscriber: currentClient.isSubscriber || isSubscriber,
              birthday: birthday || currentClient.birthday, // Manter o birthday se já existe
              whatsapp: nextWhatsapp,
              subscriberPaymentStatus: currentClient.subscriberPaymentStatus || subscriberPaymentStatus || null,
            });
          } else {
            const displayWhatsapp = String(rawWhatsapp || '').replace(/\D/g, '') || key;
            clientsMap.set(key, {
              id: profileId, // Usar o ID real do perfil
              name: clientName,
              count: 1,
              completed: isDone ? 1 : 0,
              spent: isDone ? safeValue : 0,
              isSubscriber: isSubscriber,
              birthday: birthday,
              whatsapp: displayWhatsapp,
              subscriberPaymentStatus: subscriberPaymentStatus || null,
            });
          }
        }
      });

      // Converte o mapa de clientes para um array e atualiza o estado
      const uniqueClients: Client[] = Array.from(
        clientsMap,
        ([key, { id, name, count, completed, spent, isSubscriber, birthday, whatsapp, subscriberPaymentStatus }]) => ({
        id, // Adicionar o ID
        whatsapp: whatsapp || key,
        name,
        appointmentCount: count,
        completedCount: completed,
        totalSpent: spent,
        isSubscriber: isSubscriber,
        birthday: birthday,
        forceAdvancePayment: false,
        lastAppointmentAt: lastVisitByWhatsapp.get(key),
        subscriberPaymentStatus: isSubscriber ? subscriberPaymentStatus || 'expired' : null,
      })
      );

      // Carregar clientes manuais do Supabase
      const manualClients = await loadManualClientsFromStorage();

      // Adicionar clientes manuais que ainda não existem na lista
      Object.values(manualClients).forEach((manualClient: any) => {
        // Garantir que o WhatsApp está limpo para comparação
        const cleanManualWhatsapp = normalizeWhatsappKey(manualClient.whatsapp);
        const existingClient = uniqueClients.find(c => {
          const cleanClientWhatsapp = normalizeWhatsappKey(c.whatsapp);
          return cleanClientWhatsapp === cleanManualWhatsapp;
        });

        if (!existingClient) {
          // Cliente manual que ainda não fez agendamentos
          uniqueClients.push({
            id: `manual_${cleanManualWhatsapp}`, // ID único para cliente manual
            whatsapp: String(manualClient.whatsapp || '').replace(/\D/g, '') || cleanManualWhatsapp,
            name: manualClient.name,
            cpf: String(manualClient.cpf || '').replace(/\D/g, '') || null,
            street: String(manualClient.street || '').trim() || null,
            appointmentCount: 0,
            isSubscriber: false,
            birthday: manualClient.birthday,
            forceAdvancePayment: manualClient.forceAdvancePayment === true,
            subscriberPaymentStatus: null,
          });
        } else {
          // Cliente manual que já fez agendamentos - usar nome mais atualizado
          existingClient.name = manualClient.name;
          // Priorizar whatsapp salvo no manual_clients (evita alternar formatos)
          existingClient.whatsapp = String(manualClient.whatsapp || '').replace(/\D/g, '') || existingClient.whatsapp;
          existingClient.cpf = String(manualClient.cpf || '').replace(/\D/g, '') || existingClient.cpf || null;
          existingClient.street = String(manualClient.street || '').trim() || existingClient.street || null;
          if (manualClient.birthday) {
            existingClient.birthday = manualClient.birthday;
          }
          existingClient.forceAdvancePayment = manualClient.forceAdvancePayment === true;
        }
      });

      // Carregar aniversários do Supabase primeiro, depois localStorage como fallback
      const supabaseBirthdays = await loadBirthdaysFromSupabase();
      const localBirthdays = loadBirthdaysFromStorage();

      // Mesclar: Supabase tem prioridade
      const allBirthdays = { ...localBirthdays, ...supabaseBirthdays };

      uniqueClients.forEach(client => {
        const keys = possibleWhatsappLookupKeys(client.whatsapp);
        const savedBirthday = keys.map((k) => allBirthdays[k]).find(Boolean);
        if (savedBirthday) {
          client.birthday = savedBirthday.birthday;
        }
      });

      // Carregar alertas do Supabase primeiro, depois localStorage como fallback
      const supabaseAlerts = await loadAlertsFromSupabase();
      const localAlerts = loadAlertsFromStorage();

      // Mesclar: Supabase tem prioridade
      const allAlerts = { ...localAlerts, ...supabaseAlerts };

      uniqueClients.forEach(client => {
        const keys = possibleWhatsappLookupKeys(client.whatsapp);
        const savedAlert = keys.map((k) => allAlerts[k]).find(Boolean);
        if (savedAlert) {
          client.alert = savedAlert.alert;
        }
      });

      // ✅ Buscar faltas no banco (interno) e mesclar por WhatsApp
      try {
        const { data: faltasData, error: faltasErr } = await supabase
          .from('client_no_shows')
          .select('client_whatsapp, misses')
          .eq('establishment_id', establishment.id);

        if (!faltasErr) {
          const map = new Map<string, number>();
          (faltasData as any[])?.forEach((r: any) => {
            const phone = String(r.client_whatsapp || '').replace(/\D/g, '');
            const keys = possibleWhatsappLookupKeys(phone).map((k) => String(k || '').replace(/\D/g, ''));
            keys.forEach((k) => {
              if (!k) return;
              map.set(k, Number(r.misses || 0));
            });
          });
          uniqueClients.forEach((c) => {
            const keys = possibleWhatsappLookupKeys(c.whatsapp).map((k) => String(k || '').replace(/\D/g, ''));
            const found = keys.map((k) => map.get(k)).find((v) => v !== undefined);
            c.faltas = found ?? 0;
          });
        } else {
          const msg = String((faltasErr as any)?.message || '');
          console.warn('⚠️ Não foi possível carregar faltas (client_no_shows):', faltasErr);
          if (msg.includes('does not exist') || msg.includes('schema cache')) {
            uniqueClients.forEach((c) => (c.faltas = 0));
          }
        }
      } catch (e) {
        console.warn('⚠️ Falha ao mesclar faltas no fetchClients:', e);
      }

      setClients(uniqueClients);
    } catch (error: any) {
      console.error('Erro ao buscar clientes:', error);
      toast(error.message || 'Erro ao carregar clientes', 'error');
    }
  };

  const addPremiumDrawColumns = async () => {
    try {
      const { error } = await supabase.rpc('execute_sql', {
        sql: `
          ALTER TABLE premium_subscribers
          ADD COLUMN IF NOT EXISTS is_winner boolean DEFAULT false,
          ADD COLUMN IF NOT EXISTS winner_position integer,
          ADD COLUMN IF NOT EXISTS last_draw_date timestamp with time zone;
        `
      });

      if (error) {
        throw error;
      }

      toast('Colunas adicionadas com sucesso', 'success');
    } catch (error) {
      console.error('Erro ao adicionar colunas:', error);
      toast('Erro ao adicionar colunas', 'error');
    }
  };

  // Função para gerar o slug do estabelecimento
  const generateSlug = (name: string, code: string) => {
    const normalizedName = name
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');

    return `${normalizedName}-${code}`;
  };

  const copyLinkToClipboard = async () => {
    if (!establishment) return;

    const link = `${window.location.origin}/booking/${establishment.code}`;

    try {
      // Tentar usar a API moderna do clipboard
      if (navigator.clipboard && window.isSecureContext) {
        await navigator.clipboard.writeText(link);
        toast('Link copiado para a área de transferência', 'success');
      } else {
        // Fallback para navegadores mais antigos ou não-HTTPS
        const textArea = document.createElement('textarea');
        textArea.value = link;
        textArea.style.position = 'fixed';
        textArea.style.left = '-999999px';
        textArea.style.top = '-999999px';
        document.body.appendChild(textArea);
        textArea.focus();
        textArea.select();

        try {
          document.execCommand('copy');
          toast('Link copiado para a área de transferência', 'success');
        } catch (err) {
          console.error('Erro ao copiar:', err);
          toast('Erro ao copiar link. Tente selecionar manualmente.', 'error');
        }

        document.body.removeChild(textArea);
      }
    } catch (err) {
      console.error('Erro ao copiar link:', err);
      toast('Erro ao copiar link. Tente selecionar manualmente.', 'error');
    }
  };

  // Função para migrar dados antigos de horários para nova estrutura
  const migrateBusinessHours = (oldBusinessHours: any): Record<string, BusinessHours> => {
    if (!oldBusinessHours) {
      return {
        monday: { enabled: true, open1: '09:00', close1: '12:00', open2: '13:30', close2: '18:00' },
        tuesday: { enabled: true, open1: '09:00', close1: '12:00', open2: '13:30', close2: '18:00' },
        wednesday: { enabled: true, open1: '09:00', close1: '12:00', open2: '13:30', close2: '18:00' },
        thursday: { enabled: true, open1: '09:00', close1: '12:00', open2: '13:30', close2: '18:00' },
        friday: { enabled: true, open1: '09:00', close1: '12:00', open2: '13:30', close2: '18:00' },
        saturday: { enabled: false, open1: '09:00', close1: '12:00', open2: '13:30', close2: '18:00' },
        sunday: { enabled: false, open1: '09:00', close1: '12:00', open2: '13:30', close2: '18:00' }
      };
    }

    const days = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
    return days.reduce((acc, day) => {
      const dayHours = oldBusinessHours[day];
      acc[day] = {
        enabled: dayHours?.enabled ?? true,
        open1: dayHours?.open1 || '09:00',
        close1: dayHours?.close1 || '12:00',
        open2: dayHours?.open2 || '13:30',
        close2: dayHours?.close2 || '18:00'
      };
      return acc;
    }, {} as Record<string, BusinessHours>);
  };

